 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Each existing contiguous nonzero run of length > 1 is a pattern.
    patterns = []
    pattern_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                seq = row[start:c]
                patterns.append(seq)
                pattern_cells.update((r, j) for j in range(start, c))

    # A solitary colored cell identifies a pattern; align its matching color
    # in that pattern with the cell, clipping any part beyond the grid edges.
    for r, row in enumerate(grid):
        for anchor, color in enumerate(row):
            if color == 0 or (r, anchor) in pattern_cells:
                continue
            for seq in patterns:
                if color not in seq:
                    continue
                start = anchor - seq.index(color)
                for i, value in enumerate(seq):
                    c = start + i
                    if 0 <= c < w:
                        out[r][c] = value
                break
    return out
